$('#start').onclick=()=>{start();$('#start').blur();};$('#retry').onclick=()=>{reset();$('#retry').blur();};$('#restart').onclick=()=>{reset();$('#restart').blur();};$('#mobile-retry').onclick=()=>{reset();$('#mobile-retry').blur();};$('#rotate-tip').onclick=()=>{document.documentElement.classList.add('rotate-dismissed');};$('#pause').onclick=()=>togglePause();$('#resume').onclick=()=>{togglePause(false);audio.init();};
